diff --git a/src/core/compiler/backend/railshot/amd64/hints.go b/src/core/compiler/backend/railshot/amd64/hints.go
index f1d390b60..f62611541 100644
--- a/src/core/compiler/backend/railshot/amd64/hints.go
+++ b/src/core/compiler/backend/railshot/amd64/hints.go
@@ -966,6 +966,21 @@ type byteBodyScanner struct {
 func (s *byteBodyScanner) notePhysicalEvent(op byte, depth int) {
 	var kind shared.LocalEventKind
 	switch op {
+	case 0x01: // NOP rejects a sizing shape; the main scanner handles density.
+		if s.map32Shape != 0 {
+			s.map32Shape |= map32HintInvalid
+		}
+		return
+	case 0x6c, 0x94: // scalar multiply; avoid changing the main instruction switch
+		if s.map32Shape != 0 {
+			if op == 0x6c {
+				s.map32Shape |= map32HintMulI32
+			} else {
+				s.map32Shape |= map32HintMulF32
+			}
+		}
+		return
+
 	case 0x02, 0x1f:
 		kind = shared.LocalEventBlock
 	case 0x03:
@@ -1225,20 +1240,6 @@ func (s *byteBodyScanner) scanExpr(depth int, loopDepth int, curLoop int, stopAt
 			if s.map32Shape != 0 && label == 0 {
 				s.map32Shape |= map32HintBranch
 			}
-		case 0x01: // nop: scalar oracle and a known planner rejection
-			if s.map32Shape != 0 {
-				s.map32Shape |= map32HintInvalid
-			}
-			s.noteImmediateFreeOp()
-		case 0x6c, 0x94: // scalar multiply, also used by the capacity estimate
-			if s.map32Shape != 0 {
-				if op == 0x6c {
-					s.map32Shape |= map32HintMulI32
-				} else {
-					s.map32Shape |= map32HintMulF32
-				}
-			}
-			s.noteImmediateFreeOp()
 		case 0x00, 0x0f: // unreachable, return
 			s.h.flags.set(hintHasControlFlow)
 			s.entryPrefix = false
